import{_ as e,c as l,a,o as t}from"./app-C_dHcy8Q.js";const c={};function o(s,i){return t(),l("div",null,[...i[0]||(i[0]=[a('<h1 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h1><p>签名校验失败（401/403）</p><ul><li>症状：返回 401/403，日志含 &quot;signature invalid&quot; 或 &quot;timestamp skew&quot;</li><li>排查：检查 <code>X-Timestamp</code> 与服务器时钟偏差；确认 HMAC 串拼接顺序与 secret 一致</li><li>解决：同步时间（NTP）、适当放宽 <code>ANALYTICS_INGEST_SKEW</code></li></ul><p>被限流（429）</p><ul><li>症状：短时间返回 429</li><li>排查：查看 Ingestion 限流规则（按游戏/环境/来源）</li><li>解决：降低上报频率或申请配额；确认客户端重试退避策略</li></ul><p>数据延迟</p><ul><li>症状：看板延迟 5~15 分钟</li><li>排查：Redis/Kafka 积压、Worker 错误日志、ClickHouse 写入延迟</li><li>解决：扩容 Worker、调整批量与 flush 周期、开启死信旁路</li></ul><p>维度爆炸/查询很慢</p><ul><li>症状：ClickHouse 查询超时或扫描量过大</li><li>排查：高基数字段（如 uid、ip、trace_id）是否被错误作为维度聚合</li><li>解决：对高基数做采样/哈希聚合；拆分明细表与聚合表；限制自由查询</li></ul><p>仪表板空白</p><ul><li>症状：Grafana 面板无数据</li><li>排查：数据源配置、查询时间范围、预置变量、表名/列名</li><li>解决：先用 SQL 验证数据，再修正面板查询</li></ul>',11)])])}const r=e(c,[["render",o]]),u=JSON.parse('{"path":"/analytics/troubleshooting.html","title":"故障排除","lang":"zh-CN","frontmatter":{"title":"故障排除"},"git":{"updatedTime":1763325744000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"}]},"filePathRelative":"analytics/troubleshooting.md"}');export{r as comp,u as data};
